use clap::{Parser, Subcommand};

#[derive(Parser)]
#[command(name = "oranda")]
#[command(author = "oranda contributors")]
#[command(version = "0.6.5")]
#[command(about = "🎁 generate beautiful landing pages for your projects", long_about = None)]
struct Cli {
    #[command(subcommand)]
    command: Commands,

    /// Whether to output more detailed debug information
    #[arg(short, long, global = true)]
    verbose: bool,

    /// The format of the output
    #[arg(long, global = true, default_value = "human")]
    output_format: OutputFormat,
}

#[derive(Debug, Clone)]
enum OutputFormat {
    Human,
    Json,
}

impl std::str::FromStr for OutputFormat {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "human" => Ok(OutputFormat::Human),
            "json" => Ok(OutputFormat::Json),
            _ => Err(format!("Invalid output format: {}", s)),
        }
    }
}

#[derive(Subcommand)]
enum Commands {
    /// Build an oranda site
    Build {
        /// Only build the artifacts JSON file (if applicable) and other files that may be used to
        /// support it, such as installer source files
        #[arg(long)]
        json_only: bool,
    },

    /// Start a local development server that recompiles your oranda site if a file changes
    Dev {
        /// The port for the file server to be launched on
        #[arg(long)]
        port: Option<u16>,

        /// Skip the first build before starting to watch for changes
        #[arg(long)]
        no_first_build: bool,

        /// List of extra paths to watch
        #[arg(short, long)]
        include_paths: Option<Vec<String>>,
    },

    /// Start a file server to access your oranda site in a browser
    Serve {
        /// Server port
        #[arg(long, default_value = "7979")]
        port: u16,
    },

    /// Generate infrastructure files for oranda sites
    Generate {
        #[command(subcommand)]
        command: GenerateCommands,

        /// Path to the output file
        #[arg(short, long)]
        output_path: Option<String>,

        /// Path to your oranda site
        #[arg(short, long)]
        site_path: Option<String>,
    },
}

#[derive(Subcommand)]
enum GenerateCommands {
    /// Generates a CI file that can be used to deploy your site
    Ci {
        /// What CI to generate a file for
        #[arg(long, default_value = "github")]
        ci: CiType,
    },
}

#[derive(Debug, Clone)]
enum CiType {
    Github,
}

impl std::str::FromStr for CiType {
    type Err = String;

    fn from_str(s: &str) -> Result<Self, Self::Err> {
        match s {
            "github" => Ok(CiType::Github),
            _ => Err(format!("Invalid CI type: {}", s)),
        }
    }
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let cli = Cli::parse();

    if cli.verbose {
        tracing_subscriber::fmt::fmt()
            .with_max_level(tracing::Level::DEBUG)
            .init();
    }

    match cli.command {
        Commands::Build { json_only } => {
            handle_build(json_only).await?;
        }
        Commands::Dev {
            port,
            no_first_build,
            include_paths,
        } => {
            handle_dev(port, no_first_build, include_paths).await?;
        }
        Commands::Serve { port } => {
            handle_serve(port).await?;
        }
        Commands::Generate {
            command,
            output_path,
            site_path,
        } => {
            handle_generate(command, output_path, site_path).await?;
        }
    }

    Ok(())
}

async fn handle_build(json_only: bool) -> anyhow::Result<()> {
    // Build the site
    println!("Building oranda site...");
    if json_only {
        println!("Building JSON artifacts only...");
    }
    Ok(())
}

async fn handle_dev(
    port: Option<u16>,
    no_first_build: bool,
    include_paths: Option<Vec<String>>,
) -> anyhow::Result<()> {
    println!("Starting development server...");
    if let Some(p) = port {
        println!("Port: {}", p);
    }
    if no_first_build {
        println!("Skipping first build...");
    }
    if let Some(paths) = include_paths {
        println!("Watching additional paths: {:?}", paths);
    }
    Ok(())
}

async fn handle_serve(port: u16) -> anyhow::Result<()> {
    println!("✓ >o_o< SUCCESS: Your project is available at: http://127.0.0.1:{}/", port);
    // Keep the server running
    loop {
        tokio::time::sleep(tokio::time::Duration::from_secs(1)).await;
    }
}

async fn handle_generate(
    command: GenerateCommands,
    output_path: Option<String>,
    site_path: Option<String>,
) -> anyhow::Result<()> {
    match command {
        GenerateCommands::Ci { ci } => {
            println!("Generating CI configuration...");
            if let Some(p) = output_path {
                println!("Output path: {}", p);
            }
            if let Some(p) = site_path {
                println!("Site path: {}", p);
            }
        }
    }
    Ok(())
}
EOF

