use std::env;
use std::process;

fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        print_help();
        process::exit(0);
    }

    match args[1].as_str() {
        "--version" | "-V" => {
            println!("oranda 0.6.5");
        }
        "--help" | "-h" => {
            print_help();
        }
        "build" => {
            handle_build(&args[2..]);
        }
        "dev" => {
            handle_dev(&args[2..]);
        }
        "serve" => {
            handle_serve(&args[2..]);
        }
        "generate" => {
            handle_generate(&args[2..]);
        }
        "help" => {
            if args.len() > 2 {
                match args[2].as_str() {
                    "build" => print_help_build(),
                    "dev" => print_help_dev(),
                    "serve" => print_help_serve(),
                    "generate" => print_help_generate(),
                    _ => print_help(),
                }
            } else {
                print_help();
            }
        }
        _ => {
            eprintln!("Unknown command: {}", args[1]);
            print_help();
            process::exit(1);
        }
    }
}

fn print_help() {
    println!("🎁 generate beautiful landing pages for your projects");
    println!();
    println!("Usage: oranda [OPTIONS] <COMMAND>");
    println!();
    println!("Commands:");
    println!("  build     Build an oranda site");
    println!("  dev       Start a local development server that recompiles your oranda site if a file changes");
    println!("  serve     Start a file server to access your oranda site in a browser");
    println!("  generate  Generate infrastructure files for oranda sites");
    println!("  help      Print this message or the help of the given subcommand(s)");
    println!();
    println!("Options:");
    println!("  -h, --help");
    println!("          Print help (see a summary with '-h')");
    println!();
    println!("  -V, --version");
    println!("          Print version");
    println!();
    println!("GLOBAL OPTIONS:");
    println!("  -v, --verbose");
    println!("          Whether to output more detailed debug information");
    println!();
    println!("      --output-format <OUTPUT_FORMAT>");
    println!("          The format of the output");
    println!();
    println!("          [default: human]");
    println!();
